-- Fall 2026 Volunteer Bulletin: Disability Program/Camp Volunteer
-- (Youth/Teenagers) Opportunities, grouped by Region -> County.
--
-- Run this once in the Supabase dashboard: SQL Editor -> New query -> paste -> Run.
-- Safe to run on the existing project: it adds the new region/county
-- columns (no-op if they already exist), clears the old sample volunteer
-- row(s), and inserts the full Fall 2026 list below.

alter table public.volunteers
  add column if not exists region text not null default '',
  add column if not exists county text not null default '';

delete from public.volunteers;

